Item.method_code:
//Innovatorオブジェクト生成
var iomInv = aras.IomInnovator;
var hiddenFlg = false;
var disableFlg = true;

// ユーザからエイリアスアイデンティティを取得
const currentUserId = aras.getUserID();
var alias = iomInv.newItem("Alias", "get");
alias.setProperty("source_id", currentUserId);
alias.setAttribute('select', 'related_id');
alias = alias.apply();
var aliasId = alias.getProperty("related_id");
var identityList = aras.getIdentityList();
var isMember = false;

// 検索グリッドの選択行ステータスによる有効化判定
var selectedRowsCount = options.getState().grid.selectedRows.length;

// 公開のマルQマスタが1つ選択されている時のみ活性化、管理者のみボタンを表示
// 選択行のItemId取得
for (var i = 0; i < selectedRowsCount; i++) {
    var selectedItemId = options.getState().grid.selectedRows[i];
    
    // 選択行のItem取得
    var selectedItem = iomInv.newItem(options.itemTypeName, "get");
    selectedItem.setID(selectedItemId);
    selectedItem.setAttribute("select", "managed_by_id");
    selectedItem = selectedItem.apply();
    var selectedItemManagedbyid = selectedItem.getProperty("managed_by_id");
    
    //managed_byのアイデンティティにユーザのエイリアスアイデンティティが含まれるかどうか判定
    if(selectedItemManagedbyid == null || selectedItemManagedbyid == "")
    {
        isMember = false;
    }
    else
    {
      isMember = (identityList.indexOf(selectedItemManagedbyid) >= 0); 
    }
    
    if(isMember)
    {
        hiddenFlg = false;
        disableFlg = false;
    }
    else
    {
        hiddenFlg = true;
        disableFlg = true;
        break;
    }
    
    // 公開のマルQマスタが1つ選択されている時のみ活性化、管理者のみボタンを表示
    if (selectedRowsCount != 1) 
    {
        disableFlg = true;
    }
    
}

return {hidden: hiddenFlg,disabled: disableFlg};
